#!/bin/bash
# This script generates the TMA Moda/K8s configuration for a new stamp.

set -e

if [ -z "$2" ]; then
  echo "Usage: $0 <stamp_name> <stamp_env>"
  echo "e.g. $0 prod-weu-01 prod"
  exit 1
fi

tma_repo="../.."

export STAMP_NAME=$1
export STAMP_ENV=$2
export STAMP_NAME_UNDERSCORED=$(echo "$STAMP_NAME" | tr '-' '_')
export STAMP_NAME_ALPHANUM=$(echo "$STAMP_NAME" | tr -d '-')

# If moda environment does not exist in deployment.yaml, add it
if ! yq eval --exit-status ".environments[] | select(.name == \"$STAMP_NAME\")" $tma_repo/config/moda/deployment.yaml 2>&1 >/dev/null; then
  if [ $STAMP_ENV == "prod" ]; then
    yq -i ".environments += [{\"name\": \"$STAMP_NAME\", \"auto_deploy\": true, \"service_mesh\": {\"enabled\": true}, \"cluster_selector\": {\"profile\": \"proxima\", \"stamp\": \"$STAMP_NAME\"}, \"required_review_tasks\": [], \"skip_auto_merge\": true, \"require_pipeline\": true}]" $tma_repo/config/moda/deployment.yaml
  else
    yq -i ".environments += [{\"name\": \"$STAMP_NAME\", \"auto_deploy\": true, \"service_mesh\": {\"enabled\": true}, \"cluster_selector\": {\"profile\": \"proxima\", \"stamp\": \"$STAMP_NAME\"}, \"required_review_tasks\": [], \"skip_auto_merge\": true, \"required_builds\": [\"build\"]}]" $tma_repo/config/moda/deployment.yaml
  fi
fi

if [ $STAMP_ENV == "prod" ]; then
  export GITHUB_TELEMETRY_ENVIRONMENT="production"
  export TMA_TUF_MIRROR="https://tuf-repo.github.com"
else
  export GITHUB_TELEMETRY_ENVIRONMENT="development"
  export TMA_TUF_MIRROR="https://github.github.com/staging-tuf-root"
fi

# Generate kustomize overlay for the new stamp
template_dir="./templates/kustomize"
for file in $(cd $template_dir; find . -type f); do
    echo "Processing $file"
    output_dir="$tma_repo/config/kustomize/overlays/${STAMP_NAME}/$(dirname "$file")"
    mkdir -p "$output_dir"
    (cat <<EOF
###############################################################################################
# DO NOT EDIT THIS FILE MANUALLY. PLEASE USE THE GENERATOR SCRIPTS LOCATED IN config/generator.
###############################################################################################
EOF
    envsubst < "$template_dir/$file"
    ) > "$output_dir/$(basename "$file")"
done

echo Building kube manifests
pushd $tma_repo
gh kustomize build
